package com.rekluzlabs.makokolorize.ui.screensimport androidx.compose.foundation.Imageimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.heightimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material3.Buttonimport androidx.compose.material3.CircularProgressIndicatorimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.runtime.LaunchedEffectimport androidx.compose.runtime.getValueimport androidx.compose.runtime.mutableStateOfimport androidx.compose.runtime.rememberimport androidx.compose.runtime.rememberCoroutineScopeimport androidx.compose.runtime.setValueimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.clipimport androidx.compose.ui.res.painterResourceimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.res.stringResourceimport androidx.compose.ui.text.style.TextAlignimport androidx.compose.ui.unit.dpimport androidx.compose.ui.unit.spimport com.rekluzlabs.makokolorize.Rimport com.rekluzlabs.makokolorize.data.model.ModelRepositoryimport com.rekluzlabs.makokolorize.ui.components.AppProgressIndicatorimport kotlinx.coroutines.launchsealed class DownloadState {    data object Checking : DownloadState()    data object Ready : DownloadState()    data class Downloading(val label: String, val progress: Float) : DownloadState()    data class Error(val message: String) : DownloadState()}@Composablefun SplashScreen(    onNavigate: () -> Unit,    context: android.content.Context) {    val repo = remember { ModelRepository(context) }    val scope = rememberCoroutineScope()    var state by remember { mutableStateOf<DownloadState>(DownloadState.Checking) }    LaunchedEffect(Unit) {        if (repo.isScunetModelDownloaded()) {            onNavigate()        } else {            state = DownloadState.Ready        }    }    Column(        modifier = Modifier            .fillMaxSize()            .padding(32.dp),        horizontalAlignment = Alignment.CenterHorizontally,        verticalArrangement = Arrangement.Center    ) {        Image(            painter = painterResource(id = R.mipmap.ic_launcher_foreground),            contentDescription = "App Logo",            modifier = Modifier                .size(150.dp)                .clip(RoundedCornerShape(32.dp))        )        Spacer(modifier = Modifier.height(24.dp))        Text(            text = "makokolorize",            fontSize = 32.sp,            fontWeight = FontWeight.Bold        )        Spacer(modifier = Modifier.height(8.dp))        Text(            text = "Colorize your black & white photos",            fontSize = 16.sp,            textAlign = TextAlign.Center        )        Spacer(modifier = Modifier.height(48.dp))        when (val currentState = state) {            is DownloadState.Checking -> {                CircularProgressIndicator()                Spacer(modifier = Modifier.height(16.dp))                Text("Checking for models...")            }            is DownloadState.Ready -> {                val missingModels = buildList {                    if (!repo.isModelDownloaded()) add("DDColor")                    if (!repo.isScunetModelDownloaded()) add("SCUNet")                }                val freeSpace = repo.getFreeSpaceBytes()                if (freeSpace < ModelRepository.REQUIRED_FREE_SPACE) {                    Text(                        "Low storage: ${freeSpace / 1_000_000}MB free, need ${ModelRepository.REQUIRED_FREE_SPACE / 1_000_000}MB",                        color = MaterialTheme.colorScheme.error,                        textAlign = TextAlign.Center                    )                    Spacer(modifier = Modifier.height(8.dp))                }                Button(onClick = {                    state = DownloadState.Downloading("DDColor", 0f)                    scope.launch {                        downloadModels(repo) { s ->                            state = s                        }.onSuccess {                            onNavigate()                        }.onFailure { e ->                            state = DownloadState.Error(e.message ?: "Download failed")                        }                    }                }) {                    Text(stringResource(R.string.download_model))                }                Spacer(modifier = Modifier.height(16.dp))                Text(                    text = stringResource(R.string.download_warning_note),                    style = MaterialTheme.typography.bodySmall,                    textAlign = TextAlign.Center,                    modifier = Modifier.padding(horizontal = 16.dp),                    color = MaterialTheme.colorScheme.onSurfaceVariant                )            }            is DownloadState.Downloading -> {                Text(                    text = "Downloading ${currentState.label}...",                    fontSize = 14.sp,                    color = MaterialTheme.colorScheme.onSurfaceVariant                )                Spacer(modifier = Modifier.height(8.dp))                AppProgressIndicator(progress = currentState.progress)                Spacer(modifier = Modifier.height(8.dp))                Text("${(currentState.progress * 100).toInt()}%")                Spacer(modifier = Modifier.height(16.dp))                Text(                    text = stringResource(R.string.downloading_disclaimer),                    style = MaterialTheme.typography.bodySmall,                    textAlign = TextAlign.Center,                    modifier = Modifier.padding(horizontal = 16.dp),                    color = MaterialTheme.colorScheme.onSurfaceVariant                )            }            is DownloadState.Error -> {                Text(                    currentState.message,                    color = MaterialTheme.colorScheme.error,                    textAlign = TextAlign.Center                )                Spacer(modifier = Modifier.height(16.dp))                Button(onClick = {                    state = DownloadState.Downloading("DDColor", 0f)                    scope.launch {                        downloadModels(repo) { s ->                            state = s                        }.onSuccess {                            onNavigate()                        }.onFailure { e ->                            state = DownloadState.Error(e.message ?: "Download failed")                        }                    }                }) {                    Text(stringResource(R.string.retry))                }            }        }    }}private suspend fun downloadModels(    repo: ModelRepository,    onState: (DownloadState) -> Unit): Result<Unit> {    if (!repo.isModelDownloaded()) {        onState(DownloadState.Downloading("DDColor", 0f))        repo.downloadModel { progress ->            onState(DownloadState.Downloading("DDColor", progress))        }.getOrElse { return Result.failure(it) }    }    if (!repo.isScunetModelDownloaded()) {        onState(DownloadState.Downloading("SCUNet", 0f))        repo.downloadScunetModel { progress ->            onState(DownloadState.Downloading("SCUNet", progress))        }.getOrElse { return Result.failure(it) }    }    return Result.success(Unit)}